template <typename T> struct DefaultPolicy {
    static constexpr bool Log = false;
};

template <typename T, bool D = true> struct DebugPolicy {
    static constexpr bool Log = D;
};

template <typename T, template <typename> class Policy = DefaultPolicy>
class ServiceWrapper {
    T payload;
    void operation() {
        if constexpr (Policy<T>::Log) { /* Log message */ }
    }
};

ServiceWrapper<int> S1;
ServiceWrapper<float, DebugPolicy> S2;

